def split(s: str, platform: str = 'this') -> List[str]:
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        # POSIX-style path splitting
        return re.split(r'/', s)
    elif platform == 'nt':
        # Windows/CMD-style path splitting
        return re.split(r'\\', s)
    else:
        raise ValueError(f"Unsupported platform: {platform}")

