def add_new_tile(grid):
    empty_cells = [(row, col) for row in range(4) for col in range(4) if grid[row][col] == 0]
    if empty_cells:
        row, col = empty_cells[random.randint(0, len(empty_cells) - 1)]
        grid[row][col] = 2 if random.random() < 0.9 else 4
    return grid

def check_game_over(grid):
    for row in range(4):
        for col in range(4):
            if grid[row][col] == 0:
                return False
            if row < 3 and grid[row][col] == grid[row + 1][col]:
                return False
            if col < 3 and grid[row][col] == grid[row][col + 1]:
                return False
    return True

def move_up(grid):
    for col in range(4):
        for row in range(1, 4):
            if grid[row][col] != 0:
                r = row
                while r > 0 and grid[r - 1][col] == 0:
                    r -= 1
                if r > 0 and grid[r - 1][col] == grid[row][col]:
                    grid[r - 1][col] *= 2
                    grid[row][col] = 0
                else:
                    grid[r][col] = grid[row][col]
                    if r != row:
                        grid[row][col] = 0
    return grid

def move_down(grid):
    for col in range(4):
        for row in range(2, -1, -1):
            if grid[row][col] != 0:
                r = row
                while r < 3 and grid[r + 1][col] == 0:
