def move_right(grid):
    for row in range(4):
        for col in range(2, -1, -1):
            if grid[row][col] != 0:
                c = col
                while c < 3 and grid[row][c + 1] == 0:
                    c += 1
                if c < 3 and grid[row][c + 1] == grid[row][col]:
                    grid[row][c + 1] *= 2
                    grid[row][col] = 0
                else:
                    grid[row][c] = grid[row][col]
                    if c != col:
                        grid[row][col] = 0
    return grid

class Game:
    def __init__(self):
        self.grid = [[0] * 4 for _ in range(4)]
        self.score = 0

    def add_new_tile(self):
        self.grid = add_new_tile(self.grid)

    def check_game_over(self):
        return check_game_over(self.grid)

    def draw_grid(self):
        draw_grid(self.grid)

    def move(self, direction):
        moved = False
        if direction == 'UP':
            self.grid = move_up(self.grid)
            moved = True
        elif direction == 'DOWN':
            self.grid = move_down(self.grid)
            moved = True
        elif direction == 'LEFT':
            self.grid = move_left(self.grid)
            moved = True
        elif direction == 'RIGHT':
            self.grid = move_right(self.grid)
            moved = True
        if moved:
            self.add_new_tile()
        return moved

    def handle_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                return False
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_UP:
                    self.move('UP')
                elif event.key == pygame.K_DOWN:
                    self.move('DOWN')
                elif event.key == pygame.K_LEFT:
                    self.move('LEFT')
                elif event.key == pygame.K_RIGHT:
                    self.move('RIGHT')
            self.draw_grid()
            pygame.display.flip()
            if self.check_game_over():
                return False
        return True

def main():
    game = Game()
    running = True
    while running:
        running = game.handle_events()
    pygame.quit()
    sys.exit()

