@dataclass
class Bookmarks:
    bookmarks: List[Bookmark]

def from_raw_values(values: List[str]) -> Bookmarks:
    bookmarks = []
    for value in values:
        parts = value.split('\t')
        if len(parts) == 2:
            name, url = parts
            bookmarks.append(Bookmark(name, url))
    return Bookmarks(bookmarks)
